# A wizard walks a person through a manual procedure, one stage at a time.
# Generated by the personal-wizard skill.
# Run it with: powershell -ExecutionPolicy Bypass -File <this file>
#
# Everything above the STAGES marker is the wizard library: do not hand-edit it.
# Write the stages inside Invoke-Wizard, below the marker.
# Keep this file pure ASCII: Windows PowerShell 5.1 misreads other characters.

Set-StrictMode -Version 2
$ErrorActionPreference = 'Stop'

# ------------------------------------------------------------------------------
# Wizard library: the same in every wizard.
# ------------------------------------------------------------------------------

# Set by the author at the top of Invoke-Wizard.
$script:TotalStages = 0
$script:StageIndex = 0

# The file that keeps captured values between runs, one KEY=value per line.
# Set WIZARD_CAPTURE_FILE to choose it; keep it outside any repo.
# Example: C:\Users\<you>\wizard-values\qa-deploy.txt
$script:CaptureFile = if ($env:WIZARD_CAPTURE_FILE) { $env:WIZARD_CAPTURE_FILE } else { Join-Path $env:TEMP 'wizard-values.txt' }
$script:Saved = New-Object System.Collections.ArrayList
$script:Skipped = New-Object System.Collections.ArrayList
# Keys read with Ask-Secret. Save-Value encrypts these with Windows DPAPI (current user only).
$script:SecretKeys = New-Object System.Collections.ArrayList

# Clears the console so only the current stage is visible; does nothing when output is redirected.
function Clear-WizardScreen {
  if (-not [Console]::IsOutputRedirected) { Clear-Host }
}

function Say([string]$Text) { Write-Host "  $Text" }
function Step([string]$Text) { Write-Host '  * ' -ForegroundColor Cyan -NoNewline; Write-Host $Text }
function Note([string]$Text) { Write-Host "  $Text" -ForegroundColor DarkGray }
function Warn([string]$Text) { Write-Host "  ! $Text" -ForegroundColor Yellow }

# Waits until the person presses Enter.
function Wait-Step([string]$Prompt = 'Press Enter to continue') {
  [void](Read-Host "  $Prompt")
}

# Asks a yes/no question; returns $true only for an answer starting with y.
function Confirm-Step([string]$Question) {
  $reply = Read-Host "  ? $Question [y/N]"
  return ($reply -match '^[Yy]')
}

# Shows the opening frame: the title, the stage count and how the wizard works.
function Show-Banner([string]$Title) {
  Clear-WizardScreen
  Write-Host ''
  Write-Host "  $Title" -ForegroundColor Cyan
  Write-Host "  $($script:TotalStages) stages" -ForegroundColor DarkGray
  Note 'You do the clicks. The wizard says exactly what to do and saves the values you paste back.'
  Note 'Stop any time with Ctrl+C. Run it again later and saved values come back as defaults.'
  Wait-Step 'Ready to start? Press Enter'
}

# Clears the screen and announces the next stage with its number.
function Start-Stage([string]$Name) {
  Clear-WizardScreen
  $script:StageIndex++
  Write-Host ''
  Write-Host ("  > Stage {0}/{1} - {2}" -f $script:StageIndex, $script:TotalStages, $Name) -ForegroundColor Cyan
}

# Opens a URL, a file or a program (for example inetmgr or ssms).
function Open-Target([string]$Target) {
  Write-Host "  -> opening $Target" -ForegroundColor Green
  try { Start-Process $Target } catch { Warn "could not open it, so open it by hand: $Target" }
}

# Returns the value saved for KEY in the capture file, or $null.
function Get-SavedValue([string]$Key) {
  if (-not (Test-Path -LiteralPath $script:CaptureFile)) { return $null }
  $line = Get-Content -LiteralPath $script:CaptureFile | Where-Object { $_.StartsWith("$Key=") } | Select-Object -Last 1
  if ($null -eq $line) { return $null }
  $value = $line.Substring($Key.Length + 1)
  if ($value.StartsWith('dpapi:')) {
    try {
      $secure = ConvertTo-SecureString $value.Substring(6)
      $ptr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
      try { return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr) }
      finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr) }
    } catch { return $null }  # saved by another Windows user or machine: ask again
  }
  return $value
}

# Writes KEY=value to the capture file, replacing any earlier line for KEY.
# A key read with Ask-Secret is stored DPAPI-encrypted, never as plain text.
function Save-Value([string]$Key, [string]$Value) {
  $lines = @()
  if (Test-Path -LiteralPath $script:CaptureFile) {
    $lines = @(Get-Content -LiteralPath $script:CaptureFile | Where-Object { -not $_.StartsWith("$Key=") })
  }
  $stored = $Value
  if ($script:SecretKeys.Contains($Key)) {
    $stored = 'dpapi:' + (ConvertTo-SecureString $Value -AsPlainText -Force | ConvertFrom-SecureString)
  }
  $lines += "$Key=$stored"
  Set-Content -LiteralPath $script:CaptureFile -Value $lines -Encoding ASCII
  Set-Variable -Name $Key -Value $Value -Scope Script
  if (-not $script:Saved.Contains($Key)) { [void]$script:Saved.Add($Key) }
  Write-Host "  saved $Key -> $($script:CaptureFile)" -ForegroundColor Green
}

# Asks for a visible value; Enter keeps the saved one. Returns the answer.
function Ask([string]$Key, [string]$Prompt) {
  $current = Get-SavedValue $Key
  $suffix = if ($current) { " [Enter keeps: $current]" } else { '' }
  $answer = Read-Host "  $Prompt$suffix"
  if (-not $answer -and $current) { $answer = $current }
  Set-Variable -Name $Key -Value $answer -Scope Script
  return $answer
}

# Like Ask, but the typing is hidden. Returns the answer as plain text.
function Ask-Secret([string]$Key, [string]$Prompt) {
  if (-not $script:SecretKeys.Contains($Key)) { [void]$script:SecretKeys.Add($Key) }
  $current = Get-SavedValue $Key
  $suffix = if ($current) { ' [Enter keeps the saved value]' } else { '' }
  $secure = Read-Host "  $Prompt$suffix" -AsSecureString
  $ptr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
  try { $answer = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr) }
  finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr) }
  if (-not $answer -and $current) { $answer = $current }
  Set-Variable -Name $Key -Value $answer -Scope Script
  return $answer
}

# Records something the wizard could not do, for the closing summary.
function Add-Skipped([string]$What) { [void]$script:Skipped.Add($What) }

# Shows the closing summary: what was saved and what is still to do by hand.
function Show-Finish {
  Clear-WizardScreen
  Write-Host ''
  Write-Host '  Done' -ForegroundColor Green
  if ($script:Saved.Count) { Note ("saved {0} value(s) to {1}: {2}" -f $script:Saved.Count, $script:CaptureFile, ($script:Saved -join ', ')) }
  if ($script:Skipped.Count) {
    Warn 'still to do by hand:'
    foreach ($s in $script:Skipped) { Note "  - $s" }
  }
  Write-Host ''
}

# ------------------------------------------------------------------------------
# STAGES: write this section. One Start-Stage per step the person takes.
# Replace the example below and set $script:TotalStages to match.
# Keep every stage inside Invoke-Wizard and keep the last line as it is.
# ------------------------------------------------------------------------------

function Invoke-Wizard {

$script:TotalStages = 2

Show-Banner 'Deploy a DLL to the QA box'

# -- Example stage: replace with your real steps --------------------------------
Start-Stage 'QA box: back up the current DLL'
Say 'Before anything changes, keep a copy of the DLL that is there now.'
Step 'Open Remote Desktop and sign in to the QA web server.'
[void](Ask 'QA_SERVER' 'QA server name (example: qa-web-01):')
[void](Ask 'DLL_PATH' 'Full path of the DLL on that server (example: D:\apps\bin\Thing.dll):')
Step "Copy $DLL_PATH to the same folder with .bak-<today> on the end of its name."
Wait-Step 'Press Enter when the backup copy exists'

Start-Stage 'QA box: replace and register the DLL'
if (-not (Confirm-Step "Overwrite $DLL_PATH on $QA_SERVER now?")) {
  Add-Skipped "replace $DLL_PATH on $QA_SERVER"
} else {
  Step 'Copy the new DLL over the old one.'
  Step "Run in an admin prompt on the server: regsvr32 `"$DLL_PATH`""
  Step 'IIS Manager -> Application Pools -> the site''s pool -> Recycle.'
  Wait-Step 'Press Enter when the page loads again'
}
# ------------------------------------------------------------------------------

Show-Finish
}

Invoke-Wizard; exit
